import React, { useState, useEffect, useCallback } from "react";
import "../styles/Admin.css";

function Admin() {
  // --- State Variables ---
  const [file, setFile] = useState(null);
  const [section, setSection] = useState("authors"); // Default section
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [materials, setMaterials] = useState(""); // New field for paintings
  const [paintingSize, setPaintingSize] = useState(""); // New field for paintings
  const [message, setMessage] = useState(""); // For user feedback (success/error)
  const [isUploading, setIsUploading] = useState(false); // To disable buttons during upload
  const [uploadedFiles, setUploadedFiles] = useState([]); // Stores the list of files for the current section
  const [stats, setStats] = useState({}); // Stores upload statistics

  // --- API Base URL ---
  // !!! Your Render backend URL is correctly integrated here !!!
  const API_BASE_URL = "https://backend3-nam9.onrender.com"; 

  // --- Handlers for Input Changes ---
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    setFile(selectedFile);
    
    setMessage(""); // Clear previous message when a new file is selected
    
    // Display file info if a file is selected
    if (selectedFile) {
      setMessage(`Selected: ${selectedFile.name} (${(selectedFile.size / 1024 / 1024).toFixed(2)} MB)`);
    }
  };

  const handleSectionChange = (e) => {
    const newSection = e.target.value;
    setSection(newSection);
    // Clear form fields when section changes to avoid confusion
    setTitle("");
    setDescription("");
    setMaterials(""); // Clear materials field
    setPaintingSize(""); // Clear painting size field
    setFile(null); // Also clear the file selection
    setMessage(""); // Clear any previous messages
  };

  // --- Helper Function to Get Dynamic Labels ---
  const getFieldLabel = () => {
    switch (section) {
      case "authors":
        return { title: "Author Name", description: "Biography/Details" };
      case "paintings":
        return { title: "Painting Title", description: "Description/Story" };
      case "exhibitions":
        return { title: "Exhibition Name", description: "Details/Information" };
      default:
        return { title: "Title", description: "Description" };
    }
  };

  // --- File Upload Logic ---
  const handleUpload = async () => {
    // --- Input Validations ---
    if (!file) {
      setMessage("❌ Please select a file first!");
      return;
    }
    if (!file.type.startsWith('image/')) {
      setMessage("❌ Please select an image file!");
      return;
    }
    // Title validation - prompt user if empty
    if (!title.trim()) {
      const confirmUpload = window.confirm(
        `You haven't entered a ${getFieldLabel().title.toLowerCase()}. Upload anyway?`
      );
      if (!confirmUpload) return; // Stop upload if user cancels
    }

    // --- Prepare Upload ---
    setIsUploading(true);
    setMessage("⏳ Uploading...");

    const formData = new FormData();
    formData.append("file", file);
    formData.append("section", section);
    formData.append("title", title.trim());
    formData.append("description", description.trim());
    
    // Add new fields for paintings section
    if (section === "paintings") {
      formData.append("materials", materials.trim());
      formData.append("paintingSize", paintingSize.trim());
    }

    // --- Make API Call ---
    try {
      const res = await fetch(`${API_BASE_URL}/upload`, {
        method: "POST",
        body: formData,
      });

      const data = await res.json();

      // --- Handle Response ---
      if (res.ok) { // Typically 200 or 201 status codes
        setMessage(`✅ Upload successful! File saved to "${section}" section.`);
        setFile(null); // Clear the file input
        setTitle(""); // Clear title
        setDescription(""); // Clear description
        setMaterials(""); // Clear materials
        setPaintingSize(""); // Clear painting size
        // Clear the file input element itself
        document.querySelector('input[type="file"]').value = '';
        
        // Refresh the list of uploaded files and stats
        loadFiles(); // Fetch current files for the section
        loadStats(); // Refresh stats
      } else {
        // Handle backend errors (e.g., file too large, invalid format, etc.)
        setMessage(`❌ Upload failed: ${data.error || "Unknown error"}`);
      }
    } catch (err) {
      // Handle network errors or issues during the fetch operation
      console.error("Upload error:", err);
      setMessage("❌ Upload failed: Network error. Ensure backend is running and accessible.");
    } finally {
      setIsUploading(false); // Always re-enable buttons after attempt
    }
  };

  // --- Fetching Uploaded Files ---
  const loadFiles = useCallback(async () => { // Wrapped in useCallback
    try {
      const res = await fetch(`${API_BASE_URL}/files/${section}`);
      if (!res.ok) {
        throw new Error(`HTTP error! status: ${res.status}`);
      }
      const data = await res.json();
      setUploadedFiles(data.files || []);
    } catch (err) {
      console.error("Error loading files:", err);
      // Don't set a message here if it's just a temporary error during navigation,
      // or handle it more gracefully if needed. For now, just log to console.
      // setMessage(`❌ Failed to load files for ${section}: ${err.message}`);
    }
  }, [section, API_BASE_URL]); // Dependency array includes section and API_BASE_URL

  // --- Fetching Upload Statistics ---
  const loadStats = useCallback(async () => { // Wrapped in useCallback
    try {
      const res = await fetch(`${API_BASE_URL}/stats`);
      if (!res.ok) {
        throw new Error(`HTTP error! status: ${res.status}`);
      }
      const data = await res.json();
      setStats(data.stats || {});
    } catch (err) {
      console.error("Error loading stats:", err);
      // Don't set a message here if it's just a temporary error, or handle it more gracefully.
      // setMessage(`❌ Failed to load stats: ${err.message}`);
    }
  }, [API_BASE_URL]); // Dependency array includes API_BASE_URL

  // --- Deleting a File ---
  const deleteFile = async (filename) => {
    if (!window.confirm(`Are you sure you want to delete "${filename}"?`)) return;

    try {
      const res = await fetch(`${API_BASE_URL}/delete`, {
        method: "DELETE",
        headers: { 
          "Content-Type": "application/json",
          // Add any other headers your backend might need, like auth tokens
        },
        body: JSON.stringify({ filename, section }), // Send filename and section to backend
      });

      const data = await res.json();
      
      if (res.ok) {
        setMessage(`✅ "${filename}" deleted successfully!`);
        loadFiles(); // Refresh list after deletion
        loadStats(); // Refresh stats after deletion
      } else {
        setMessage(`❌ Delete failed: ${data.error || "Unknown error"}`);
      }
    } catch (err) {
      console.error("Delete error:", err);
      setMessage("❌ Delete failed: Network error. Ensure backend is running.");
    }
  };

  // --- Effect Hooks ---
  // Load files when the section changes
  useEffect(() => {
    loadFiles();
  }, [loadFiles]); // Dependency on loadFiles (thanks to useCallback)

  // Load stats on component mount
  useEffect(() => {
    loadStats();
  }, [loadStats]); // Dependency on loadStats (thanks to useCallback)

  // Get field labels once
  const fieldLabels = getFieldLabel();

  // --- JSX Rendering ---
  return (
    <div className="admin-body">
      <h2 className="admin-title">📁 File Upload Admin</h2>
      
      {/* Stats Display */}
      <div className="admin-stats">
        <h3 className="stats-title">📊 Upload Statistics:</h3>
        {Object.keys(stats).length > 0 ? (
          <div className="stats-container">
            {Object.entries(stats).map(([key, count]) => (
              <div key={key} className="stat-item">
                <strong>{key.charAt(0).toUpperCase() + key.slice(1)}:</strong> {count} file(s)
              </div>
            ))}
          </div>
        ) : (
          <p className="no-stats">No upload data available. Try uploading some files!</p>
        )}
      </div>

      {/* Upload Form */}
      <div className="upload-form">
        <h3 className="upload-title">📤 Upload New File</h3>
        
        <div className="form-group">
          <label className="form-label">Section: </label>
          <select 
            value={section} 
            onChange={handleSectionChange}
            disabled={isUploading} // Disable dropdown while uploading
            className="section-select"
          >
            <option value="authors">👤 Authors</option>
            <option value="paintings">🎨 Paintings</option>
            <option value="exhibitions">🏛️ Exhibitions</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">{fieldLabels.title}: </label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            disabled={isUploading} // Disable input while uploading
            className="text-input"
            placeholder={`Enter ${fieldLabels.title.toLowerCase()}`}
            maxLength={100}
            required 
          />
        </div>

        <div className="form-group">
          <label className="form-label">{fieldLabels.description}: </label>
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            disabled={isUploading} // Disable textarea while uploading
            className="textarea-input"
            placeholder={`Enter ${fieldLabels.description.toLowerCase()}`}
            rows={3}
            maxLength={10000}
          />
        </div>

        {/* New fields for paintings section only */}
        {section === "paintings" && (
          <>
            <div className="form-group">
              <label className="form-label">Materials: </label>
              <input
                type="text"
                value={materials}
                onChange={(e) => setMaterials(e.target.value)}
                disabled={isUploading}
                className="text-input"
                placeholder="Enter materials used (e.g., Oil on canvas, Acrylic, Watercolor)"
                maxLength={200}
              />
            </div>

            <div className="form-group">
              <label className="form-label">Size: </label>
              <input
                type="text"
                value={paintingSize}
                onChange={(e) => setPaintingSize(e.target.value)}
                disabled={isUploading}
                className="text-input"
                placeholder="Enter painting size (e.g., 24 x 36 inches, 60 x 90 cm)"
                maxLength={100}
              />
            </div>
          </>
        )}

        <div className="form-group">
          <label className="form-label">Select Image: </label>
          <input 
            type="file" 
            accept="image/*" // Restrict file type to images
            onChange={handleFileChange} 
            disabled={isUploading} // Disable file input while uploading
            className="file-input"
          />
        </div>

        <button 
          onClick={handleUpload}
          disabled={isUploading || !file} // Disable button if uploading or no file selected
          className={`upload-btn ${isUploading ? 'uploading' : ''} ${!file ? 'disabled' : ''}`}
        >
          {isUploading ? '⏳ Uploading...' : '📤 Upload'}
        </button>

        {/* Message display (success or error) */}
        {message && (
          <p className={`message ${message.includes('✅') ? 'success' : 'error'}`}>
            {message}
          </p>
        )}
      </div>

      {/* File List Display */}
      <div className="file-list-section">
        <h3 className="file-list-title">📋 Files in "{section}" section ({uploadedFiles.length})</h3>
        {uploadedFiles.length > 0 ? (
          <div className="file-grid">
            {uploadedFiles.map((file, index) => (
              <div key={index} className="file-card"> 
                <img 
                  // Construct the full URL to the image, pointing to your Render backend
                  src={`${API_BASE_URL}${file.url}`} 
                  alt={file.metadata?.title || file.filename || `Image from ${section}`}
                  className="file-thumbnail"
                  onError={(e) => { // Handle broken image icons
                    e.target.style.display = 'none'; // Hide the broken image element
                  }}
                />
                
                <div className="file-info">
                  {/* Display title if it exists */}
                  {file.metadata?.title && (
                    <h4 className="file-title">{file.metadata.title}</h4>
                  )}
                  
                  {/* Display filename */}
                  <p className="file-name">{file.filename}</p>
                  
                  {/* Display description, truncated if long */}
                  {file.metadata?.description && (
                    <p className="file-description">
                      {file.metadata.description.length > 100 
                        ? `${file.metadata.description.substring(0, 100)}...` 
                        : file.metadata.description
                      }
                    </p>
                  )}
                  
                  {/* Display materials and size for paintings */}
                  {section === "paintings" && (
                    <>
                      {file.metadata?.materials && (
                        <p className="file-materials">
                          <strong>Materials:</strong> {file.metadata.materials}
                        </p>
                      )}
                      {file.metadata?.paintingSize && (
                        <p className="file-size">
                          <strong>Size:</strong> {file.metadata.paintingSize}
                        </p>
                      )}
                    </>
                  )}
                </div>
                
                {/* Delete Button */}
                <button 
                  onClick={() => deleteFile(file.filename)}
                  className="delete-btn"
                >
                  🗑️ Delete
                </button>
              </div>
            ))}
          </div>
        ) : (
          // Message when no files are found for the selected section
          <p className="no-files">No files uploaded yet for the "{section}" section.</p>
        )}
      </div>
    </div>
  );
}

export default Admin;