import React, { useState, useEffect } from 'react';
import { Phone, Mail, MapPin, MessageCircle } from 'lucide-react';
import { Link } from 'react-router-dom';
import Footer from './Footer';
import '../styles/Contact.css';

function Contact() {
  const [isVisible, setIsVisible] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  const phoneNumber = "593933212";
  const email = "artgalleryvake@gmail.com";
  const address = "ირაკლი აბაშიძე, 47 / Ir.Abashidze, 47";

  const handleWhatsAppClick = () => {
    window.open(`https://wa.me/995${phoneNumber}`, '_blank');
  };

  const handleViberClick = () => {
    window.open(`viber://chat?number=+995${phoneNumber}`, '_blank');
  };

  const handleEmailClick = () => {
    window.location.href = `mailto:${email}`;
  };

  const handlePhoneClick = () => {
    window.location.href = `tel:+995${phoneNumber}`;
  };

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  const closeSidebar = () => {
    setSidebarOpen(false);
  };

  return (
    <div className="contact-body">
      {/* Header */}
      <header className={`landing-header ${isVisible ? 'fade-in' : ''}`}>
        <div className="logo-container">
          <div className="logo-text">
            <h2>Art Gallery</h2>
            <span>Vake</span>
          </div>
        </div>
        
        {/* Desktop Navigation */}
        <nav className="nav-links desktop-nav">
          <a href="/" className="nav-link">მთავარი</a>
          <a href="/" className="nav-link">ავტორები</a>
          <a href="/" className="nav-link">ნამუშევრები</a>
          <a href="/" className="nav-link">გამოფენები</a>
          <a href="/contact" className="nav-link active">კონტაქტი</a>
        </nav>

        {/* Mobile Menu Button */}
        <button className="mobile-menu-btn" onClick={toggleSidebar}>
          <span></span>
          <span></span>
          <span></span>
        </button>
      </header>

      {/* Mobile Sidebar */}
      <div className={`sidebar ${sidebarOpen ? 'sidebar-open' : ''}`}>
        <div className="sidebar-content">
          <button className="sidebar-close" onClick={closeSidebar}>×</button>
          <nav className="sidebar-nav">
            <a href="/" className="sidebar-link" onClick={closeSidebar}>მთავარი</a>
            <a href="/" className="sidebar-link" onClick={closeSidebar}>ავტორები</a>
            <a href="/" className="sidebar-link" onClick={closeSidebar}>ნამუშევრები</a>
            <a href="/" className="sidebar-link" onClick={closeSidebar}>გამოფენები</a>
            <Link
              to="/contact"
              className="sidebar-link active"
              onClick={() => {
                window.scrollTo(0, 0);
                closeSidebar();
              }}
            >
              კონტაქტი
            </Link>
          </nav>
        </div>
      </div>

      {/* Sidebar Overlay */}
      {sidebarOpen && <div className="sidebar-overlay" onClick={closeSidebar}></div>}

      {/* Contact Content */}
      <div className="contact-container">
        <div className="contact-content">
          <h1 className="contact-title">კონტაქტი</h1>
          <p className="contact-subtitle">მოგვწერეთ ან დაგვირეკეთ</p>

          <div className="contact-grid">
            {/* Contact Information */}
            <div className="contact-info">
              <div className="contact-card">
                <div className="contact-item">
                  <Phone className="contact-icon" />
                  <div className="contact-details">
                    <h3>ტელეფონი</h3>
                    <p
                      className="contact-link"
                      onClick={handlePhoneClick}
                    >
                      +995 {phoneNumber.replace(/(\d{3})(\d{3})(\d{2})(\d{2})/, '$1 $2 $3 $4')}
                    </p>
                  </div>
                </div>

                <div className="contact-item">
                  <Mail className="contact-icon" />
                  <div className="contact-details">
                    <h3>ელ-ფოსტა</h3>
                    <p
                      className="contact-link"
                      onClick={handleEmailClick}
                    >
                      {email}
                    </p>
                  </div>
                </div>

                <div className="contact-item">
                  <MapPin className="contact-icon" />
                  <div className="contact-details">
                    <h3>მისამართი</h3>
                    <p>{address}</p>
                  </div>
                </div>
              </div>

              {/* Social/Messaging Apps */}
              <div className="messaging-apps">
                <h3>დაგვიკავშირდით:</h3>
                <div className="messaging-buttons">
                  <button
                    className="messaging-btn whatsapp-btn"
                    onClick={handleWhatsAppClick}
                  >
                    <MessageCircle size={20} />
                    WhatsApp
                  </button>
                  <button
                    className="messaging-btn viber-btn"
                    onClick={handleViberClick}
                  >
                    <MessageCircle size={20} />
                    Viber
                  </button>
                </div>
              </div>
            </div>

            {/* Google Map */}
            <div className="map-container">
              <iframe
                src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2978.094621837969!2d44.78366821544!3d41.70736077923!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x404472d7f0e61c5d%3A0x47b3b9b8a7a5b8a5!2sIrakli%20Abashidze%20St%2047%2C%20T%27bilisi%2C%20Georgia!5e0!3m2!1sen!2sge!4v1644567890123!5m2!1sen!2sge"
                width="100%"
                height="400"
                style={{ border: 0 }}
                allowFullScreen=""
                loading="lazy"
                referrerPolicy="no-referrer-when-downgrade"
                title="Art Gallery Vake Location"
              ></iframe>
            </div>
          </div>

          {/* Additional Info */}
          <div className="gallery-hours">
            <h3>სამუშაო საათები</h3>
            <div className="hours-grid">
              <div className="hours-item">
                <span>ორშაბათი - პარასკევი:</span>
                <span>10:00 - 19:00</span>
              </div>
              <div className="hours-item">
                <span>შაბათი - კვირა:</span>
                <span>11:00 - 18:00</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      <Footer />
    </div>
  );
}

export default Contact;