import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import slugify from 'slugify';
import "../styles/AuthorPage.css";

function AuthorPage() {
  const { authorSlug } = useParams();
  const [authorData, setAuthorData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Use the same createSlug function as in Home.js
  const createSlug = (text) => {
    if (!text) return '';
    return slugify(text, {
      lower: true,
      strict: false,
      remove: /[*+~.()'"!:@]/g,
      replacement: '-',
      trim: true
    });
  };

  const formatDescription = (text) => {
    if (!text) return null;
    const paragraphs = text.split(/\n\s*\n/);
    return paragraphs.map((paragraph, index) => {
      const trimmedParagraph = paragraph.trim();
      const lines = trimmedParagraph.split('\n');
      const isBulletList = lines.some(line => 
        /^\s*[-*•]\s/.test(line) || /^\s*\d+\.\s/.test(line)
      );

      if (isBulletList) {
        const listItems = lines.map((line, lineIndex) => {
          const trimmedLine = line.trim();
          if (/^[-*•]\s/.test(trimmedLine)) {
            return <li key={lineIndex} className="bullet-item">{trimmedLine.replace(/^[-*•]\s/, '')}</li>;
          } else if (/^\d+\.\s/.test(trimmedLine)) {
            return <li key={lineIndex} className="numbered-item">{trimmedLine.replace(/^\d+\.\s/, '')}</li>;
          } else if (trimmedLine) {
            return <li key={lineIndex} className="text-item" style={{listStyle: 'none'}}>{trimmedLine}</li>;
          }
          return null;
        }).filter(item => item !== null);

        const hasNumbered = lines.some(line => /^\s*\d+\.\s/.test(line));
        return hasNumbered ? (
          <ol key={index} className="description-list numbered-list">{listItems}</ol>
        ) : (
          <ul key={index} className="description-list bullet-list">{listItems}</ul>
        );
      } else {
        const formattedParagraph = lines.map((line, lineIndex) => (
          <React.Fragment key={lineIndex}>
            {line}
            {lineIndex < lines.length - 1 && <br />}
          </React.Fragment>
        ));
        return <p key={index} className="description-paragraph">{formattedParagraph}</p>;
      }
    });
  };

  // --- DEPLOYED BACKEND URL ---
  const BACKEND_URL = "https://backend3-nam9.onrender.com";

  useEffect(() => {
    const fetchAuthorData = async () => {
      try {
        setLoading(true);
        setError(null);
        const response = await fetch(BACKEND_URL + "/files/authors");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();

        const foundAuthor = data.files.find(file =>
          file.metadata?.title && createSlug(file.metadata.title) === authorSlug
        );

        if (foundAuthor) {
          setAuthorData(foundAuthor);
        } else {
          setError("Author not found.");
        }
      } catch (err) {
        console.error("Error fetching author data:", err);
        setError("Failed to load author details.");
      } finally {
        setLoading(false);
      }
    };

    fetchAuthorData();
  }, [authorSlug]);

  if (loading) return <div className="author-page-container"><div className="loading-message">Loading author details...</div></div>;
  if (error) return <div className="author-page-container"><div className="error-message">{error}</div></div>;
  if (!authorData) return <div className="author-page-container"><div className="error-message">No author data available.</div></div>;

  return (
    <div className="author-page-container">
      <div className="back-button-container">
        <Link to="/" className="back-button">
          <span className="arrow">&larr;</span> საწყისი
        </Link>
      </div>

      <div className="author-details">
        <div className="author-image-container">
          <img
            src={`${BACKEND_URL}${authorData.url}`}
            alt={authorData.metadata?.title || 'Author'}
            className="author-detail-image"
            onError={(e) => { e.target.style.display = 'none'; }}
          />
        </div>

        <div className="author-info">
          {authorData.metadata?.title && <h1 className="author-title">{authorData.metadata.title}</h1>}
          {authorData.metadata?.description && (
            <div className="author-description">{formatDescription(authorData.metadata.description)}</div>
          )}
          {!authorData.metadata?.title && <h1 className="author-title">{authorData.filename}</h1>}
        </div>
      </div>
    </div>
  );
}

export default AuthorPage;