import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import slugify from 'slugify';
import "../styles/PaintingPage.css";
function PaintingPage() {
const { paintingSlug } = useParams();
const [paintingData, setPaintingData] = useState(null);
const [loading, setLoading] = useState(true);
const [error, setError] = useState(null);
const createSlug = (text) => {
if (!text) return '';
return slugify(text, {
lower: true,
strict: false,
remove: /[*+~.()'"!:@„""`']/g,
replacement: '-',
trim: true,
locale: 'ka'
 });
 };
// --- DEPLOYED BACKEND URL ---
const BACKEND_URL = "https://backend3-nam9.onrender.com";
useEffect(() => {
const fetchPaintingData = async () => {
try {
setLoading(true);
setError(null);
const response = await fetch(BACKEND_URL + "/files/paintings");
if (!response.ok) {
throw new Error(`HTTP error! status: ${response.status}`);
 }
const data = await response.json();
const foundPainting = data.files.find(file => {
const titleSlug = file.metadata?.title ? createSlug(file.metadata.title) : '';
const filenameSlug = file.filename ? "painting-" + file.filename.split('.')[0] : '';
return titleSlug === paintingSlug || filenameSlug === paintingSlug;
 });
if (foundPainting) {
setPaintingData(foundPainting);
 } else {
setError("Painting not found.");
 }
 } catch (err) {
console.error("Error fetching painting data:", err);
setError("Failed to load painting details.");
 } finally {
setLoading(false);
 }
 };
fetchPaintingData();
 }, [paintingSlug]);
if (loading) return <div className="painting-page-container">Loading painting details...</div>;
if (error) return <div className="painting-page-container error-message">{error}</div>;
if (!paintingData) return <div className="painting-page-container">No painting data available.</div>;
const title = paintingData.metadata?.title;
const description = paintingData.metadata?.description;
const materials = paintingData.metadata?.materials;
const paintingSize = paintingData.metadata?.paintingSize;
const altText = title || paintingData.filename;
return (
<div className="painting-page-container">
<div className="back-button-container">
<Link to="/" className="back-button">
<span className="arrow">&larr;</span> საწყისი
</Link>
</div>
<div className="painting-display-area">
<img
src={BACKEND_URL + paintingData.url}
alt={altText}
className="painting-image-large"
/>
<div className="painting-details">
<h1 className="painting-name">{title || paintingData.filename}</h1>
{description && (
<p className="painting-description">{description}</p>
 )}
<div className="painting-metadata">
{materials && (
<div className="metadata-item">
<span className="metadata-label">Materials:</span>
<span className="metadata-value">{materials}</span>
</div>
 )}
{paintingSize && (
<div className="metadata-item">
<span className="metadata-label">Size:</span>
<span className="metadata-value">{paintingSize}</span>
</div>
 )}
</div>
{!description && !materials && !paintingSize && (
<p className="no-description-message">No additional details available for this painting.</p>
 )}
</div>
</div>
</div>
 );
}
export default PaintingPage;