import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import slugify from 'slugify';
import "../styles/ExhibitionPage.css";

function ExhibitionPage() {
  const { exhibitionSlug } = useParams();
  const [exhibitionData, setExhibitionData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Use the same createSlug function as in AuthorPage
  const createSlug = (text) => {
    if (!text) return '';
    return slugify(text, {
      lower: true,
      strict: false,
      remove: /[*+~.()'"!:@]/g,
      replacement: '-',
      trim: true
    });
  };

  // --- DEPLOYED BACKEND URL ---
  const BACKEND_URL = "https://backend3-nam9.onrender.com";

  useEffect(() => {
    const fetchExhibitionData = async () => {
      try {
        setLoading(true);
        setError(null);
        const response = await fetch(BACKEND_URL + "/files/exhibitions");
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();

        const foundExhibition = data.files.find(file =>
          file.metadata?.title && createSlug(file.metadata.title) === exhibitionSlug
        );

        if (foundExhibition) {
          setExhibitionData(foundExhibition);
        } else {
          setError("Exhibition not found.");
        }
      } catch (err) {
        console.error("Error fetching exhibition data:", err);
        setError("Failed to load exhibition details.");
      } finally {
        setLoading(false);
      }
    };

    fetchExhibitionData();
  }, [exhibitionSlug]);

  if (loading) {
    return <div className="exhibition-page-container"><div className="loading-message">Loading exhibition details...</div></div>;
  }

  if (error) {
    return <div className="exhibition-page-container"><div className="error-message">{error}</div></div>;
  }

  if (!exhibitionData) {
    return <div className="exhibition-page-container"><div className="error-message">No exhibition data available.</div></div>;
  }

  return (
    <div className="exhibition-page-container">
      <div className="back-button-container">
        <Link to="/" className="back-button">
          <span className="arrow">&larr;</span> საწყისი
        </Link>
      </div>

      <div className="exhibition-content">
        <img
          src={BACKEND_URL + exhibitionData.url}
          alt={exhibitionData.metadata?.title || exhibitionData.filename}
          className="exhibition-image-large"
        />
        <div className="exhibition-info-text">
          <h1 className="exhibition-name">{exhibitionData.metadata?.title || exhibitionData.filename}</h1>
          {exhibitionData.metadata?.description ? (
            <p className="exhibition-description">{exhibitionData.metadata.description}</p>
          ) : (
            <p className="no-description-message">No details available for this exhibition.</p>
          )}
        </div>
      </div>
    </div>
  );
}

export default ExhibitionPage;