import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import "../styles/Landing.css";

function Landing() {
  const [scrollY, setScrollY] = useState(0);
  const [isVisible, setIsVisible] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrollY(window.scrollY);
    window.addEventListener('scroll', handleScroll);
    setTimeout(() => setIsVisible(true), 100);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  const closeSidebar = () => {
    setSidebarOpen(false);
  };

  return (
    <div className="landing-container">
      {/* Animated Background */}
      <div className="animated-bg">
        <div className="floating-shapes">
          <div className="shape shape-1"></div>
          <div className="shape shape-2"></div>
          <div className="shape shape-3"></div>
          <div className="shape shape-4"></div>
        </div>
      </div>

      {/* Header */}
      <header className={`landing-header ${isVisible ? 'fade-in' : ''}`}>
        <div className="logo-container">
          <div className="logo-text">
            <h2>Art Gallery</h2>
            <span>Vake</span>
          </div>
        </div>
        
        {/* Desktop Navigation */}
        <nav className="nav-links desktop-nav">
          <a href="/" className="nav-link">მთავარი</a>
          <a href="/" className="nav-link">ავტორები</a>
          <a href="/" className="nav-link">ნამუშევრები</a>
          <a href="/" className="nav-link">გამოფენები</a>
          <Link
            to="/contact"
            className="nav-link"
            onClick={() => window.scrollTo(0, 0)}
          >
            კონტაქტი
          </Link>
        </nav>

        {/* Mobile Menu Button */}
        <button className="mobile-menu-btn" onClick={toggleSidebar}>
          <span></span>
          <span></span>
          <span></span>
        </button>
      </header>

      {/* Mobile Sidebar */}
      <div className={`sidebar ${sidebarOpen ? 'sidebar-open' : ''}`}>
        <div className="sidebar-content">
          <button className="sidebar-close" onClick={closeSidebar}>×</button>
          <nav className="sidebar-nav">
            <a href="/" className="sidebar-link" onClick={closeSidebar}>მთავარი</a>
            <a href="/" className="sidebar-link" onClick={closeSidebar}>ავტორები</a>
            <a href="/" className="sidebar-link" onClick={closeSidebar}>ნამუშევრები</a>
            <a href="/" className="sidebar-link" onClick={closeSidebar}>გამოფენები</a>
            <Link
              to="/contact"
              className="sidebar-link"
              onClick={() => {
                window.scrollTo(0, 0);
                closeSidebar();
              }}
            >
              კონტაქტი
            </Link>
          </nav>
        </div>
      </div>

      {/* Sidebar Overlay */}
      {sidebarOpen && <div className="sidebar-overlay" onClick={closeSidebar}></div>}

      {/* Main Content */}
      <main className="main-content">
        <div className={`content-box text-box ${isVisible ? 'slide-in-left' : ''}`}>
          <div className="main-text">
            <h1>
              <span className="text-line">Art Gallery</span>
              <span className="text-line gradient-text">Vake</span>
            </h1>
            <div className="subtitle">
              <p>Where Art Meets Soul</p>
            </div>
          </div>
          <div className="secondary-text">
            <p>
              Discover extraordinary artworks from renowned and emerging artists.
              Immerse yourself in a world where creativity knows no bounds and
              every piece tells a unique story.
            </p>
            <p>
              Experience art like never before in our carefully curated exhibitions.
            </p>
          </div>
          <div className="cta-buttons">
            <button className="btn-primary">
              <span>Explore Collection</span>
              <div className="btn-shine"></div>
            </button>
            <button className="btn-secondary">
              <span>Virtual Tour</span>
            </button>
          </div>
        </div>
        <div className={`content-box image-box ${isVisible ? 'slide-in-right' : ''}`}>
          <div className="image-container">
            <div className="image-frame">
              <img
                src={`${process.env.PUBLIC_URL}/landing.png`}
                alt="Art Gallery Vake"
                className="landing-img"
                style={{ transform: `translateY(${scrollY * 0.1}px)` }}
              />
              <div className="image-overlay"></div>
            </div>
            <div className="floating-stats">
              <div className="stat-card">
                <h3>500+</h3>
                <p>Artworks</p>
              </div>
              <div className="stat-card">
                <h3>50+</h3>
                <p>Artists</p>
              </div>
              <div className="stat-card">
                <h3>12</h3>
                <p>Exhibitions</p>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

export default Landing;